//! Target-only Gallery geometry and real-input probe; not part of product APIs.
use super::super::{Gallery, Page};
use tekes_ui_scene::{Point,Rect,Scene,Primitive};
use tekes_ui_platform_macos::{Event,Modifiers,MouseEvent,MouseEventKind,MouseButton,Point as NativePoint};
fn index(g:&Gallery)->usize {if let Page::Workbench(i)=g.page(){i}else{panic!("Workbench expected")}}
pub fn click(g:&mut Gallery,id:usize){let i=index(g);let p=g.workbench.state(i).hits.iter().rev().find(|(n,_)|*n==id).expect("real hit target").1.center();for kind in [MouseEventKind::Down{button:MouseButton::Left,click_count:1},MouseEventKind::Up{button:MouseButton::Left,click_count:1}]{g.handle_input(&Event::Mouse(MouseEvent{kind,position:NativePoint{x:p.x as f64,y:p.y as f64},modifiers:Modifiers::NONE}));}}
fn union(a:Option<Rect>,b:Rect)->Option<Rect>{Some(match a {None=>b,Some(a)=>Rect::new(a.min_x().min(b.min_x()),a.min_y().min(b.min_y()),a.max_x().max(b.max_x())-a.min_x().min(b.min_x()),a.max_y().max(b.max_y())-a.min_y().min(b.min_y()))})}
fn encoded(r:Rect)->[f32;4]{[r.min_x(),r.min_y(),r.size.width,r.size.height]}
pub fn inspect(g:&mut Gallery,scene:&Scene,scale:f32)->serde_json::Value{let i=index(g);let s=g.workbench.state(i);let preview=s.preview;let mut bad=Vec::new();let mut hits=Vec::new();for (id,r) in &s.hits {if (20..=1001).contains(id){let finite=[r.min_x(),r.min_y(),r.max_x(),r.max_y()].iter().all(|v|v.is_finite());let contained=finite && r.min_x()>=preview.min_x()-0.1 && r.max_x()<=preview.max_x()+0.1 && r.min_y()>=preview.min_y()-0.1 && r.max_y()<=preview.max_y()+0.1;if !contained{bad.push(*id);}hits.push(serde_json::json!({"id":id,"frame":encoded(*r),"contained":contained}));}}
let mut runs=Vec::new();let mut clips=vec![Rect::new(0.,0.,10000.,10000.)];for primitive in scene.primitives(){match primitive{Primitive::PushClip(r)=>{clips.push(clips.last().unwrap().intersection(r).unwrap_or(Rect::new(0.,0.,0.,0.)));},Primitive::PopClip=>{if clips.len()>1{clips.pop();}},Primitive::Glyphs(run)=>{let mut box_=None;for p in &run.glyphs{if p.glyph.width>0 && p.glyph.height>0{let r=Rect::new(((p.origin.x*scale).round()+p.glyph.left as f32)/scale,((p.origin.y*scale).round()+p.glyph.top as f32)/scale,p.glyph.width as f32/scale,p.glyph.height as f32/scale);if let Some(v)=r.intersection(clips.last().unwrap()){box_=union(box_,v);}}}if let Some(r)=box_{runs.push(r);}},_=>{}}}
let chart=if super::entry(i).renderer()=="chart"{let layout=s.extended.collections_views.chart.layout();Some(layout.geometry.bars.iter().map(|bar|{let value=bar.value_label;let cat=bar.category_label;let find=|slot:Rect|runs.iter().filter(|r|r.intersection(&slot).is_some()).min_by(|a,b|(a.center().x-slot.center().x).abs().total_cmp(&(b.center().x-slot.center().x).abs())).copied();let v=find(value);let c=find(cat);serde_json::json!({"index":bar.index,"bar":encoded(bar.rect),"value_slot":encoded(value),"category_slot":encoded(cat),"value_ink":v.map(encoded),"category_ink":c.map(encoded),"value_center_error_pt":v.map(|r|(r.center().x-bar.rect.center().x).abs()),"category_center_error_pt":c.map(|r|(r.center().x-bar.rect.center().x).abs())})}).collect::<Vec<_>>())}else{None};serde_json::json!({"preview":encoded(preview),"phase_frame":s.phase_frame.map(encoded),"event_log_frame":s.event_log_frame.map(encoded),"hits":hits,"outside_preview_hit_ids":bad,"chart":chart,"glyph_ink_rects":runs.iter().filter(|r| r.intersection(&preview).is_some()).map(|r|encoded(*r)).collect::<Vec<_>>()})}
